        switch value {


        case let .create(v1):
            writeInt(&buf, Int32(1))
            FfiConverterTypeIdentityCreateRequest.write(v1, into: &buf)


        case let .transition(v1):
            writeInt(&buf, Int32(2))
            FfiConverterTypeIdentityPreparedTransition.write(v1, into: &buf)

        }
    }
